{% set grace = {'climate.synthetic_001': 1200, 'binary_sensor.synthetic_009': 900, 'binary_sensor.synthetic_011': 900, 'binary_sensor.synthetic_010': 900} %}
{% set explicit = ['binary_sensor.synthetic_006','binary_sensor.synthetic_009','binary_sensor.synthetic_011','binary_sensor.synthetic_010'] %}
{% set monitored = (label_entities('synthetic_label_05') + explicit) | unique | list %}
{% set unavailable = label_entities('synthetic_label_04') %}
{% set ns = namespace(lines=[]) %}
{% for e in monitored %}
  {% if (e in unavailable or e in explicit) and states(e) in ['unavailable','unknown'] %}
    {% set age = (now() - states[e].last_changed).total_seconds() if states[e] is not none else 999999 %}
    {% if age >= grace.get(e, 0) %}
      {% set ns.lines = ns.lines + ['synthetic_literal_011' ~ entity_name(e) ~ 'synthetic_literal_012' ~ states(e) ~ 'synthetic_literal_013' ~ ((age/60)|round(0)|int) ~ 'synthetic_literal_014' ~ e ~ 'synthetic_literal_015'] %}
    {% endif %}
  {% endif %}
{% endfor %}
{% if states('group.synthetic_001') in ['unavailable','unknown'] %}
  {% set ns.lines = ns.lines + ['synthetic_literal_016' ~ states('group.synthetic_001') ~ 'synthetic_literal_017'] %}
{% endif %}
{{ ns.lines | join('synthetic_literal_018') }}

